<div class="table-wrap"><table><thead><tr><th>Rule Code</th><th>Stage</th><th>Actual PD</th><th>Conditions</th><th>Priority</th><th>Status</th><?php if(($showActions??false)): ?><th>Actions</th><?php endif; ?></tr></thead><tbody>
<?php foreach($rules as $rule): ?><tr><td><a class="rule-code" href="rule_view.php?id=<?= (int)$rule['id'] ?>"><?= e($rule['rule_code']) ?></a></td><td><span class="badge stage <?= e(strtolower(explode('_',$rule['stage_name'])[0])) ?>"><?= e(str_replace('_STAGE','',str_replace('_',' ',$rule['stage_name']))) ?></span></td><td><strong><?= e(number_format((float)$rule['avg_actual_pd'],2)) ?>%</strong></td><td><?= (int)$rule['condition_count'] ?> <span class="muted">AND checks</span></td><td><?= (int)$rule['priority'] ?></td><td><span class="badge <?= $rule['active']?'on':'off' ?>"><?= $rule['active']?'Active':'Inactive' ?></span></td>
<?php if(($showActions??false)): ?><td><div class="actions"><a href="rule_view.php?id=<?= (int)$rule['id'] ?>">View</a><a href="rule_edit.php?id=<?= (int)$rule['id'] ?>">Edit</a><form method="post" action="rule_action.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$rule['id'] ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="active" value="<?= $rule['active']?0:1 ?>"><button><?= $rule['active']?'Deactivate':'Activate' ?></button></form><form method="post" action="rule_action.php" data-confirm="Delete <?= e($rule['rule_code']) ?> permanently?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$rule['id'] ?>"><input type="hidden" name="action" value="delete"><button class="danger-link">Delete</button></form></div></td><?php endif; ?></tr><?php endforeach; ?>
<?php if(!$rules): ?><tr><td colspan="7" class="empty">No rules found.</td></tr><?php endif; ?></tbody></table></div>

